/**
 * Parses a potentially comma-separated multi-value header (as produced by
 * proxy chains) and returns the first value, trimmed of whitespace.
 * Returns `undefined` when the header is absent or empty, or when the
 * first value is empty/whitespace-only. Does not skip an empty first
 * value to pick a later one, since the first entry is the one closest
 * to the client and is the only one that should be trusted.
 */
export function getFirstForwardedValue(
	multiValueHeader: string | string[] | undefined,
): string | undefined {
	const first = multiValueHeader
		?.toString()
		.split(',')
		.map((e) => e.trim())[0];
	return first ? first : undefined;
}

